export function isWhitespaceCode(code) {
  return code === 32 || code === 9 || code === 10 || code === 13 || code === 12 || code === 11;
}

export function isDigitCode(code) {
  return code >= 48 && code <= 57;
}

export function isLetterCode(code) {
  return (code >= 65 && code <= 90) || (code >= 97 && code <= 122);
}

export function isWordStartCode(code) {
  return isLetterCode(code) || code === 95 || code === 36 || code > 127;
}

export function isWordCode(code) {
  return isWordStartCode(code) || isDigitCode(code);
}

export function looksLikeNegativeNumber(value) {
  if (value.length < 2 || value[0] !== '-') {
    return false;
  }

  let index = 1;
  let sawDigit = false;

  if (index < value.length && value[index] === '.') {
    index += 1;
  }

  while (index < value.length) {
    const code = value.charCodeAt(index);
    if (!isDigitCode(code)) {
      break;
    }
    sawDigit = true;
    index += 1;
  }

  if (index < value.length && value[index] === '.') {
    index += 1;
    while (index < value.length) {
      const code = value.charCodeAt(index);
      if (!isDigitCode(code)) {
        break;
      }
      sawDigit = true;
      index += 1;
    }
  }

  if (!sawDigit) {
    return false;
  }

  if (index < value.length && (value[index] === 'e' || value[index] === 'E')) {
    index += 1;
    if (index < value.length && (value[index] === '+' || value[index] === '-')) {
      index += 1;
    }

    let exponentDigits = 0;
    while (index < value.length) {
      const code = value.charCodeAt(index);
      if (!isDigitCode(code)) {
        break;
      }
      exponentDigits += 1;
      index += 1;
    }

    if (exponentDigits === 0) {
      return false;
    }
  }

  return index === value.length;
}

import { looksLikeNegativeNumber } from './char-class.mjs';

function getProgramName(pathValue) {
  if (!pathValue || pathValue.length === 0) {
    return 'test4.mjs';
  }

  let lastSeparator = -1;
  for (let index = 0; index < pathValue.length; index += 1) {
    const char = pathValue[index];
    if (char === '/' || char === '\\') {
      lastSeparator = index;
    }
  }

  return pathValue.slice(lastSeparator + 1) || pathValue;
}

export function renderHelp(programPath) {
  const programName = getProgramName(programPath);
  return `usage: ${programName} [-h] --a A

options:
  -h, --help  show this help message and exit
  --a A
`;
}

export function renderError(programPath, message) {
  const programName = getProgramName(programPath);
  return `usage: ${programName} [-h] --a A
${programName}: error: ${message}
`;
}

function isImmediateAssignment(token) {
  return token.length >= 4 && token[0] === '-' && token[1] === '-' && token[2] === 'a' && token[3] === '=';
}

function expectsValueConflict(token) {
  if (token === '-h' || token === '--help' || token === '--') {
    return true;
  }

  if (token.length < 2 || token[0] !== '-') {
    return false;
  }

  if (looksLikeNegativeNumber(token)) {
    return false;
  }

  return true;
}

export function parseCliArguments(argv) {
  let aValue = '';
  let hasAValue = false;
  let waitingForAValue = false;
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (waitingForAValue) {
      if (expectsValueConflict(token)) {
        return {
          kind: 'error',
          message: 'argument --a: expected one argument',
        };
      }

      aValue = token;
      hasAValue = true;
      waitingForAValue = false;
      continue;
    }

    if (token === '-h' || token === '--help') {
      return { kind: 'help' };
    }

    if (token === '--a') {
      waitingForAValue = true;
      continue;
    }

    if (isImmediateAssignment(token)) {
      aValue = token.slice(4);
      hasAValue = true;
      continue;
    }

    if (token === '--') {
      for (let extraIndex = index + 1; extraIndex < argv.length; extraIndex += 1) {
        extras.push(argv[extraIndex]);
      }
      break;
    }

    extras.push(token);
  }

  if (waitingForAValue) {
    return {
      kind: 'error',
      message: 'argument --a: expected one argument',
    };
  }

  if (!hasAValue) {
    return {
      kind: 'error',
      message: 'the following arguments are required: --a',
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      message: `unrecognized arguments: ${extras.join(' ')}`,
    };
  }

  return {
    kind: 'ok',
    values: {
      a: aValue,
    },
  };
}

import { isWhitespaceCode, isWordCode, isWordStartCode } from './char-class.mjs';
import { FUNCTION_LIKE_KEYWORDS, KEYWORDS } from './keywords.mjs';

function readQuotedSection(text, start, quoteChar) {
  let index = start + 1;

  while (index < text.length) {
    const current = text[index];

    if (current === '\\') {
      index += 2;
      continue;
    }

    if (current === quoteChar) {
      if (index + 1 < text.length && text[index + 1] === quoteChar) {
        index += 2;
        continue;
      }

      return index + 1;
    }

    index += 1;
  }

  return text.length;
}

function readBracketIdentifier(text, start) {
  let index = start + 1;

  while (index < text.length) {
    if (text[index] === ']') {
      if (index + 1 < text.length && text[index + 1] === ']') {
        index += 2;
        continue;
      }

      return index + 1;
    }

    index += 1;
  }

  return text.length;
}

function readLineComment(text, start) {
  let index = start + 2;

  while (index < text.length) {
    if (text[index] === '\n') {
      return index + 1;
    }
    index += 1;
  }

  return text.length;
}

function readBlockComment(text, start) {
  let index = start + 2;

  while (index + 1 < text.length) {
    if (text[index] === '*' && text[index + 1] === '/') {
      return index + 2;
    }
    index += 1;
  }

  return text.length;
}

function isDollarQuoteTagCode(code) {
  return isWordCode(code);
}

function startsDollarQuotedSection(text, start) {
  if (text[start] !== '$') {
    return '';
  }

  let index = start + 1;
  while (index < text.length) {
    const code = text.charCodeAt(index);
    if (text[index] === '$') {
      return text.slice(start, index + 1);
    }

    if (!isDollarQuoteTagCode(code)) {
      return '';
    }

    index += 1;
  }

  return '';
}

function readDollarQuotedSection(text, start) {
  const tag = startsDollarQuotedSection(text, start);
  if (tag.length === 0) {
    return start;
  }

  let index = start + tag.length;
  while (index + tag.length <= text.length) {
    let matches = true;
    for (let offset = 0; offset < tag.length; offset += 1) {
      if (text[index + offset] !== tag[offset]) {
        matches = false;
        break;
      }
    }

    if (matches) {
      return index + tag.length;
    }

    index += 1;
  }

  return text.length;
}

function readWord(text, start) {
  let index = start + 1;

  while (index < text.length) {
    const code = text.charCodeAt(index);
    if (!isWordCode(code)) {
      break;
    }
    index += 1;
  }

  return index;
}

function uppercaseWord(word) {
  return word.toUpperCase();
}

function isHorizontalWhitespaceCode(code) {
  return code === 32 || code === 9 || code === 12 || code === 11;
}

export function formatSqlWithUpperKeywords(input) {
  let output = '';
  let index = 0;
  let previousSignificantChar = '';

  while (index < input.length) {
    const current = input[index];
    const currentCode = input.charCodeAt(index);

    if (isWhitespaceCode(currentCode)) {
      output += current;
      index += 1;
      continue;
    }

    if (current === '\'' || current === '"' || current === '`') {
      const nextIndex = readQuotedSection(input, index, current);
      output += input.slice(index, nextIndex);
      previousSignificantChar = current;
      index = nextIndex;
      continue;
    }

    if (current === '[') {
      const nextIndex = readBracketIdentifier(input, index);
      output += input.slice(index, nextIndex);
      previousSignificantChar = ']';
      index = nextIndex;
      continue;
    }

    if (current === '-' && index + 1 < input.length && input[index + 1] === '-') {
      const nextIndex = readLineComment(input, index);
      output += input.slice(index, nextIndex);
      index = nextIndex;
      continue;
    }

    if (current === '/' && index + 1 < input.length && input[index + 1] === '*') {
      const nextIndex = readBlockComment(input, index);
      output += input.slice(index, nextIndex);
      index = nextIndex;
      continue;
    }

    if (current === '$') {
      const nextIndex = readDollarQuotedSection(input, index);
      if (nextIndex > index) {
        output += input.slice(index, nextIndex);
        previousSignificantChar = '$';
        index = nextIndex;
        continue;
      }
    }

    if (isWordStartCode(currentCode)) {
      const nextIndex = readWord(input, index);
      const word = input.slice(index, nextIndex);
      const upperWord = uppercaseWord(word);
      const nextChar = nextIndex < input.length ? input[nextIndex] : '';
      const shouldUppercase =
        previousSignificantChar !== '.' &&
        KEYWORDS.has(upperWord) &&
        !(nextChar === '(' && FUNCTION_LIKE_KEYWORDS.has(upperWord));

      const emitted = shouldUppercase ? upperWord : word;
      output += emitted;
      previousSignificantChar = emitted[emitted.length - 1];
      index = nextIndex;
      continue;
    }

    if (current === ';') {
      output += current;
      previousSignificantChar = current;
      index += 1;

      while (index < input.length) {
        const code = input.charCodeAt(index);
        if (!isHorizontalWhitespaceCode(code)) {
          break;
        }
        index += 1;
      }

      continue;
    }

    output += current;
    previousSignificantChar = current;
    index += 1;
  }

  return output;
}

import { parseCliArguments, renderError, renderHelp } from './lib/cli.mjs';
import { formatSqlWithUpperKeywords } from './lib/sql-formatter.mjs';

function main(argv = process.argv.slice(2), programPath = process.argv[1]) {
  const parsed = parseCliArguments(argv);

  if (parsed.kind === 'help') {
    process.stdout.write(renderHelp(programPath));
    return 0;
  }

  if (parsed.kind === 'error') {
    process.stderr.write(renderError(programPath, parsed.message));
    return 2;
  }

  const result = formatSqlWithUpperKeywords(parsed.values.a);
  process.stdout.write(`${result}\n`);
  return 0;
}

const exitCode = main();
if (exitCode !== 0) {
  process.exit(exitCode);
}

export { main };
